    { const char * tb_v1324 = "// p во временной памяти текущей (самой внутренней) области, а не во внешней\n"; *(const char * *)tb_grow(v_lines) = tb_v1324; }
    { const char * tb_v1325 = "TB_API int tb_in_cur_temp(const void *p) {\n"; *(const char * *)tb_grow(v_lines) = tb_v1325; }
    { const char * tb_v1326 = "    if (tb_temp_depth == 0) return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v1326; }
