    { const char * tb_v2395 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v2395; }
    { const char * tb_v2396 = "// строка JSON (p смотрит на \") → обычный текст\n"; *(const char * *)tb_grow(v_lines) = tb_v2396; }
    { const char * tb_v2397 = "TB_API const char *tb_js_str(const char *p) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2397; }
    { const char * tb_v2398 = "    const char *e = tb_js_skip(p);\n"; *(const char * *)tb_grow(v_lines) = tb_v2398; }
    { const char * tb_v2399 = "    if (!e) return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v2399; }
    { const char * tb_v2400 = "    char *out = tb_tmem(e - p + 1), *o = out;\n"; *(const char * *)tb_grow(v_lines) = tb_v2400; }
