    { const char * tb_v2418 = "            else if (cp < 0x10000) { *o++ = (char)(0xE0 | (cp >> 12)); *o++ = (char)(0x80 | ((cp >> 6) & 63)); *o++ = (char)(0x80 | (cp & 63)); }\n"; *(const char * *)tb_grow(v_lines) = tb_v2418; }
