    { const char * tb_v2775 = "// ---------- obj: память ----------\n"; *(const char * *)tb_grow(v_lines) = tb_v2775; }
    { const char * tb_v2776 = "// Внутри temp и шага цикла — из временной памяти, иначе — из памяти с уборкой.\n"; *(const char * *)tb_grow(v_lines) = tb_v2776; }
    { const char * tb_v2777 = "TB_API void *tb_obj_mem(long long n) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2777; }
    { const char * tb_v2778 = "    if (tb_temp_depth > 0) return tb_mem(n);\n"; *(const char * *)tb_grow(v_lines) = tb_v2778; }
